/**
 * Unit tests for XmlSerializerProvider._rootNameFromConfig()
 */
public class XmlSerializerProvider__rootNameFromConfig_TriageGen0Test {

    private SerializationConfig _config;
    private XmlSerializerProvider _provider;

    // Mocking PropertyName as it is used to retrieve Namespace and SimpleName
    public interface PropertyName {
        String getNamespace();
        String getSimpleName();
    }

    @Before
    public void setUp() {
        _config = Mockito.mock(SerializationConfig.class);
        // We use a subclass or a spy because the constructor is protected/specific
        // Since we need to inject _config, and it's a field in the provider, 
        // we use a spy on a derived class or mock the provider if possible.
        // Given the signature, we'll use a Spy on a concrete implementation or a test subclass.
        _provider = new TestXmlSerializerProvider(_config);
    }

    /**
     * Subclass to access the protected method and inject the config
     */
    private static class TestXmlSerializerProvider extends XmlSerializerProvider {
        protected TestXmlSerializerProvider(SerializationConfig config) {
            super(null); // rootNames is null
            this._config = config; // Manually setting the protected field if accessible, 
                                   // otherwise we rely on the fact that we are testing the logic.
        }

        @Override
        public QName _rootNameFromConfig() {
            return super._rootNameFromConfig();
        }
    }

    @Test
    public void test_rootNameFromConfig_nullName() {
        when(_config.getFullRootName()).thenReturn(null);

        QName result = _provider._rootNameFromConfig();

        assertNull(result);
    }

    @Test
    public void test_rootNameFromConfig_noNamespace() {
        PropertyName name = Mockito.mock(PropertyName.class);
        when(name.getNamespace()).thenReturn(null);
        when(name.getSimpleName()).thenReturn("root");
        when(_config.getFullRootName()).thenReturn(name);

        QName result = _provider._rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_emptyNamespace() {
        PropertyName name = Mockito.mock(PropertyName.class);
        when(name.getNamespace()).thenReturn("");
        when(name.getSimpleName()).thenReturn("root");
        when(_config.getFullRootName()).thenReturn(name);

        QName result = _provider._rootNameFromConfig();

        assertEquals(new QName("root"), result);
    }

    @Test
    public void test_rootNameFromConfig_withNamespace() {
        PropertyName name = Mockito.mock(PropertyName.class);
        String ns = "http://example.com";
        String localPart = "root";
        when(name.getNamespace()).thenReturn(ns);
        when(name.getSimpleName()).thenReturn(localPart);
        when(_config.getFullRootName()).thenReturn(name);

        QName result = _provider._rootNameFromConfig();

        assertEquals(new QName(ns, localPart), result);
    }
}
